<?php require_once __DIR__ . '/includes/config.php';role(['admin','hr','auditor']);$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){check();$p->prepare('INSERT INTO employees(employee_no,full_name,national_id,department,job_title,employment_status) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE full_name=VALUES(full_name),national_id=VALUES(national_id),department=VALUES(department),job_title=VALUES(job_title),employment_status=VALUES(employment_status)')->execute([$_POST['employee_no'],$_POST['full_name'],$_POST['national_id'],$_POST['department'],$_POST['job_title'],$_POST['employment_status']]);log_action('SAVE_EMPLOYEE',$_POST['employee_no']);$_SESSION['flash']='Employee saved';header('Location:employees.php');exit;}$rows=$p->query('SELECT * FROM employees ORDER BY employee_no')->fetchAll();head('Employees');?><h1>Employee register</h1><?php if(in_array($_SESSION['user']['role'],['admin','hr'])):?><form class="panel grid" method="post"><input type="hidden" name="token" value="<?=e(token())?>"><?php foreach(['employee_no'=>'Employee number','full_name'=>'Full name','national_id'=>'National ID','department'=>'Department','job_title'=>'Job title'] as $k=>$v):?><label><?=e($v)?><input name="<?=$k?>" <?=$k==='employee_no'||$k==='full_name'?'required':''?>></label><?php endforeach;?><label>Status<select name="employment_status"><?php foreach(['active','inactive','terminated','retired'] as $v):?><option><?=$v?></option><?php endforeach;?></select></label><button>Save employee</button></form><?php endif;?><div class="panel table"><table><tr><th>Number</th><th>Name</th><th>Department</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['employee_no'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['department'])?></td><td><?=e($r['employment_status'])?></td></tr><?php endforeach;?></table></div><?php foot();?>